def norm(value):
	key = str(value or "").strip().lower()
	if key in ["you", "me", "personal", "people", "for you"]:
		return "personal"
	if key in ["business", "company", "companies", "for your business"]:
		return "business"
	return "both"


def tag_of(aud):
	if aud == "personal":
		return "For you"
	if aud == "business":
		return "For your business"
	return ""


def read_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [line for line in raw.split("\n") if line.strip()]
	if not isinstance(raw, list):
		return []
	return [str(line) for line in raw if str(line).strip()]


def split_row(line, size):
	parts = [part.strip() for part in str(line).split("|")]
	while len(parts) < size:
		parts.append("")
	return parts

groups = []
try:
	order = []
	rows_by = {}
	for line in read_rows(props.get("cases")):
		parts = split_row(line, 3)
		if not parts[1]:
			continue
		aud = norm(parts[0])
		if aud not in rows_by:
			rows_by[aud] = []
			order.append(aud)
		rows_by[aud].append({"who": parts[1], "outcome": parts[2]})
	for aud in order:
		groups.append({"aud": aud, "label": tag_of(aud) or "Recent work", "rows": rows_by[aud]})
except Exception:
	groups = []
component.groups = groups
